import type { GameState } from "@core/domain/types/game.js";

/**
 * Input for a single player: either a name string (human) or an object with
 * an optional stable `id` and an optional bot config.
 *
 * Pass a stable `id` (e.g. your own user/account id) when the same person plays
 * several games, such as a Dynasty: ids are otherwise regenerated by every
 * `addPlayers` call. Ids must be non-empty and unique within one call.
 */
export type PlayerInput =
  | string
  | { id?: string; name: string; bot?: { strategyName: string } };

export type AddPlayersCommand = {
  game: GameState;
  players: PlayerInput[];
};
